import{_ as s,o as n,c as r,l as t,t as i,N as a}from"./chunks/framework.CMqbtke2.js";const m=JSON.parse('{"title":"user-session-keyring | x-cmd man (man7) | per-user default session keyring","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | user-session-keyring - per-user default session keyring","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"user-session-keyring | x-cmd man (man7) | per-user default session keyring"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | user-session-keyring - per-user default session keyring"}]]},"headers":[],"params":{"isMan":true,"man":"user-session-keyring","category":"man7","desc":"per-user default session keyring"},"relativePath":"man7/user-session-keyring.md","filePath":"man7/user-session-keyring.md"}'),o={name:"man7/user-session-keyring.md"},g={class:"visually-hidden"},h=a('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>user-session-keyring - per-user default session keyring</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The user session keyring is a keyring used to anchor keys on behalf of a user. Each UID the kernel deals with has its own user session keyring that is shared by all processes with that UID. The user session keyring has a name (description) of the form <em>_uid_ses.&lt;UID&gt;</em> where <em>&lt;UID&gt;</em> is the user ID of the corresponding user.</p><p>The user session keyring is associated with the record that the kernel maintains for the UID. It comes into existence upon the first attempt to access either the user session keyring, the <strong>user-keyring</strong>(7), or the <strong>session-keyring</strong>(7). The keyring remains pinned in existence so long as there are processes running with that real UID or files opened by those processes remain open. (The keyring can also be pinned indefinitely by linking it into another keyring.)</p><p>The user session keyring is created on demand when a thread requests it or when a thread asks for its <strong>session-keyring</strong>(7) and that keyring doesn&#39;t exist. In the latter case, a user session keyring will be created and, if the session keyring wasn&#39;t to be created, the user session keyring will be set as the process&#39;s actual session keyring.</p><p>The user session keyring is searched by <strong>request_key</strong>(2) if the actual session keyring does not exist and is ignored otherwise.</p><p>A special serial number value, <strong>KEY_SPEC_USER_SESSION_KEYRING</strong>, is defined that can be used in lieu of the actual serial number of the calling process&#39;s user session keyring.</p><p>From the <strong>keyctl</strong>(1) utility, &#39;<strong>@us</strong>&#39; can be used instead of a numeric key ID in much the same way.</p><p>User session keyrings are independent of <strong>clone</strong>(2), <strong>fork</strong>(2), <strong>vfork</strong>(2), <strong>execve</strong>(2), and <strong>_exit</strong>(2) excepting that the keyring is destroyed when the UID record is destroyed when the last process pinning it exits.</p><p>If a user session keyring does not exist when it is accessed, it will be created.</p><p>Rather than relying on the user session keyring, it is strongly recommended---especially if the process is running as root---that a <strong>session-keyring</strong>(7) be set explicitly, for example by <strong>pam_keyinit</strong>(8).</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>The user session keyring was added to support situations where a process doesn&#39;t have a session keyring, perhaps because it was created via a pathway that didn&#39;t involve PAM (e.g., perhaps it was a daemon started by <strong>inetd</strong>(8)). In such a scenario, the user session keyring acts as a substitute for the <strong>session-keyring</strong>(7).</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>keyctl</strong>(1), <strong>keyctl</strong>(3), <strong>keyrings</strong>(7), <strong>persistent-keyring</strong>(7), <strong>process-keyring</strong>(7), <strong>session-keyring</strong>(7), <strong>thread-keyring</strong>(7), <strong>user-keyring</strong>(7)</p>',16);function d(e,c,l,u,p,y){return n(),r("div",null,[t("h1",g,i(e.$params.man),1),h])}const f=s(o,[["render",d]]);export{m as __pageData,f as default};
